<?php
declare(strict_types=1);
namespace OCA\ReinhardtERP\Controller;
use OCA\ReinhardtERP\Service\BackupService;
use OCA\ReinhardtERP\Service\PermissionService;
use OCP\AppFramework\Controller;
use OCP\AppFramework\Http\Attribute\NoAdminRequired;
use OCP\AppFramework\Http\Attribute\NoCSRFRequired;
use OCP\AppFramework\Http\DataDownloadResponse;
use OCP\AppFramework\Http\RedirectResponse;
use OCP\AppFramework\Http\TemplateResponse;
use OCP\IRequest;use OCP\IURLGenerator;use OCP\ISession;
final class BackupController extends Controller{
 public function __construct(string $appName,IRequest $request,private BackupService $backups,private PermissionService $permissions,private IURLGenerator $url,private ISession $session){parent::__construct($appName,$request);}
 #[NoAdminRequired,NoCSRFRequired] public function index():TemplateResponse{$this->permissions->assert('settings');return new TemplateResponse($this->appName,'backup',['backups'=>$this->backups->list(),'settings'=>$this->backups->settings(),'message'=>(string)$this->request->getParam('message',''),'error'=>(string)$this->request->getParam('error',''),'urlGenerator'=>$this->url,'restorePreview'=>$this->session->get('betrio_backup_preview')]);}
 #[NoAdminRequired] public function create():RedirectResponse{$this->permissions->assert('settings');try{$r=$this->backups->create();return $this->go('message','Backup erstellt: '.$r['name'].' ('.$r['rows'].' Datensätze).');}catch(\Throwable $e){return $this->go('error',$e->getMessage());}}
 #[NoAdminRequired,NoCSRFRequired] public function download(string $name):DataDownloadResponse{$this->permissions->assert('settings');$c=$this->backups->content($name);return new DataDownloadResponse($c,$name,'application/octet-stream');}
 #[NoAdminRequired] public function delete(string $name):RedirectResponse{$this->permissions->assert('settings');try{$this->backups->delete($name);return $this->go('message','Backup gelöscht.');}catch(\Throwable $e){return $this->go('error',$e->getMessage());}}
 #[NoAdminRequired] public function inspect():RedirectResponse{$this->permissions->assert('settings');try{$f=$this->request->getUploadedFile('backup');if(!is_array($f)||($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new \InvalidArgumentException('Bitte eine Betrio-Backup-Datei auswählen.');if((int)($f['size']??0)>100*1024*1024)throw new \InvalidArgumentException('Das Backup darf maximal 100 MB groß sein.');$content=file_get_contents((string)$f['tmp_name']);if($content===false)throw new \RuntimeException('Backup konnte nicht gelesen werden.');$name=(string)($f['name']??'backup');$m=$this->backups->inspectContent($content,$name);$token=bin2hex(random_bytes(16));$this->session->set('betrio_backup_restore_'.$token,['content'=>base64_encode($content),'name'=>$name,'created'=>time()]);$this->session->set('betrio_backup_preview',['token'=>$token,'name'=>$name,'manifest'=>$m]);return $this->go('message','Backup erfolgreich geprüft. Noch wurden keine Daten verändert.');}catch(\Throwable $e){$this->session->remove('betrio_backup_preview');return $this->go('error',$e->getMessage());}}
 #[NoAdminRequired] public function restore():RedirectResponse{$this->permissions->assert('settings');try{$token=(string)$this->request->getParam('token','');if(!preg_match('/^[a-f0-9]{32}$/',$token))throw new \InvalidArgumentException('Die Restore-Prüfung ist ungültig. Bitte das Backup erneut prüfen.');$data=$this->session->get('betrio_backup_restore_'.$token);if(!is_array($data)||(int)($data['created']??0)<time()-1800)throw new \InvalidArgumentException('Die Restore-Prüfung ist abgelaufen. Bitte das Backup erneut prüfen.');if((string)$this->request->getParam('confirm','')!=='RESTORE')throw new \InvalidArgumentException('Bitte die Wiederherstellung ausdrücklich bestätigen.');$content=base64_decode((string)($data['content']??''),true);if($content===false)throw new \RuntimeException('Das geprüfte Backup konnte nicht geladen werden.');$m=$this->backups->restoreUploaded($content,(string)($data['name']??'backup'));$this->session->remove('betrio_backup_restore_'.$token);$this->session->remove('betrio_backup_preview');return $this->go('message','Wiederherstellung abgeschlossen. Sicherungsstand: '.(string)($m['created_at']??'unbekannt').'.');}catch(\Throwable $e){return $this->go('error',$e->getMessage());}}
 #[NoAdminRequired] public function settings(string $schedule='off',int $retention=7):RedirectResponse{$this->permissions->assert('settings');$this->backups->saveSettings($schedule,$retention);return $this->go('message','Backup-Einstellungen gespeichert.');}
 private function go(string $k,string $v):RedirectResponse{return new RedirectResponse($this->url->linkToRoute('reinhardterp.backup.index').'?'.$k.'='.rawurlencode($v));}
}
